	REAL FUNCTION CSPLN2*4(K,Y,E)
	INTEGER*2 E,K,K1
	REAL*4 Y,FF1,FF2,FF3,F1,F2,F3
C
	INTEGER*2 NS
	REAL*4 DX,DY,U,X,DEL,S
	COMMON/INDIA/DX(124),DY(124),U(124,2),X(124,2),S(124,2),
     *DEL(124,2),NS(2)
C
    2 IF(Y.LE.X(K,E))GOTO 4
	K=K+1
	GOTO 2
    4 K1=K-1
	FF1=S(K1,E)*(X(K,E)-Y)**3
	FF2=S(K,E)*(Y-X(K1,E))**3
	FF3=1.0/(6.0*DEL(K,E))
	F1=(FF1+FF2)*FF3
	F2=(Y-X(K1,E))*((U(K,E)/DEL(K,E))-(S(K,E)*DEL(K,E))/6.0)
	F3=(X(K,E)-Y)*((U(K1,E)/DEL(K,E))-(S(K1,E)*DEL(K,E))/6.0)
	CSPLN2=F1+F2+F3
	RETURN
	END
